def fizzbuzz(n: int) -> list[str]:
    """Return FizzBuzz list for 1 to n (or [] if n < 1)."""
    if n < 1:
        return []  # empty for invalid input
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")  # multiple of both
        elif i % 3 == 0:
            result.append("Fizz")  # multiple of 3 only
        elif i % 5 == 0:
            result.append("Buzz")  # multiple of 5 only
        else:
            result.append(str(i))  # plain number
    return result
